from collections import Counter

def min_window(s: str, t: str) -> str:
    if not t:
        return ''
    need = Counter(t)
    need_cnt = len(t)
    l = 0
    res = ''
    for r, ch in enumerate(s):
        if ch in need:
            if need[ch] > 0:
                need_cnt -= 1
            need[ch] -= 1
        while need_cnt == 0:
            cand = s[l:r+1]
            if not res or len(cand) < len(res):
                res = cand
            ch2 = s[l]
            if ch2 in need:
                need[ch2] += 1
                if need[ch2] > 0:
                    need_cnt += 1
            l += 1
    return res

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []
    intervals = sorted([i[:] for i in intervals])
    res = [intervals[0][:]]
    for a,b in intervals[1:]:
        la, lb = res[-1]
        if a <= lb:
            res[-1][1] = max(lb, b)
        else:
            res.append([a,b])
    return res

class TrieNode:
    __slots__ = ('children','end')
    def __init__(self):
        self.children = {}
        self.end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()
    def insert(self, word: str) -> None:
        cur = self.root
        for ch in word:
            cur = cur.children.setdefault(ch, TrieNode())
        cur.end = True
    def search(self, word: str) -> bool:
        cur = self.root
        for ch in word:
            if ch not in cur.children:
                return False
            cur = cur.children[ch]
        return cur.end
    def starts_with(self, prefix: str) -> bool:
        cur = self.root
        for ch in prefix:
            if ch not in cur.children:
                return False
            cur = cur.children[ch]
        return True

from collections import deque

def max_sliding_window(nums: list[int], k: int) -> list[int]:
    if k <= 0 or not nums:
        return []
    dq = deque()
    res = []
    for i, x in enumerate(nums):
        while dq and dq[0] <= i - k:
            dq.popleft()
        while dq and nums[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            res.append(nums[dq[0]])
    return res

class SegTree:
    def __init__(self, a: list[int]):
        n0 = len(a)
        n = 1
        while n < n0:
            n <<= 1
        self.n = n
        self.t = [0]*(2*n)
        for i,v in enumerate(a):
            self.t[n+i] = v
        for i in range(n-1, 0, -1):
            self.t[i] = self.t[i<<1] + self.t[i<<1|1]
    def point_update(self, i: int, val: int):
        p = self.n + i
        self.t[p] = val
        p >>= 1
        while p > 0:
            self.t[p] = self.t[p<<1] + self.t[p<<1|1]
            p >>= 1
    def range_sum(self, l: int, r: int) -> int:
        l += self.n; r += self.n
        res = 0
        while l <= r:
            if l & 1: res += self.t[l]; l += 1
            if (r & 1) == 0: res += self.t[r]; r -= 1
            l >>= 1; r >>= 1
        return res

