def write_csv(filename: str, data: list[dict], encoding: str = 'utf-8') -> bool:
    if not data:
        return False
    try:
        with open(filename, 'w', encoding=encoding, newline='') as f:
            writer = csv.DictWriter(f, fieldnames=data[0].keys())
            writer.writeheader()
            writer.writerows(data)
        return True
    except Exception:
        return False

